```ts
import { format, isToday } from "date-fns";

import { Code } from "@/types/base/code/code";
import { ObservationListRead } from "@/types/emr/observation/observation";

/** Which slice of the patient's record the sheet is showing. */
export type ObservationScope = "encounter" | "patient";

/** One requested code, rendered as a row in the flowsheet. */
export interface PlotRow {
  code: Code;
  /** `code.code` — the key used to look a reading up in a column's cells. */
  key: string;
  label: string;
  unit?: string;
}

/** One distinct `effective_datetime`, rendered as a column in the flowsheet. */
export interface PlotColumn {
  /** The raw `effective_datetime`. */
  key: string;
  time: number;
  label: string;
  cells: Record<string, ObservationListRead>;
}

export interface PlotPoint {
  time: number;
  value: number;
}

interface QueryParamArgs {
  codes: Code[];
  encounterId: string;
  scope: ObservationScope;
  offset: number;
  limit: number;
}

export function buildObservationQueryParams({
  codes,
  encounterId,
  scope,
  offset,
  limit,
}: QueryParamArgs): Record<string, string> {
  const params: Record<string, string> = {
    codes: codes.map((code) => code.code).join(","),
    limit: String(limit),
    offset: String(offset),
  };
  if (scope === "encounter") {
    params.encounter = encounterId;
  }
  return params;
}

/**
 * A column shares a calendar day with another, so its label needs a time to
 * stay distinguishable.
 */
function labelColumns(columns: PlotColumn[], todayLabel: string) {
  const perDay = new Map<string, number>();
  for (const column of columns) {
    const day = format(column.time, "yyyy-MM-dd");
    perDay.set(day, (perDay.get(day) ?? 0) + 1);
  }

  for (const column of columns) {
    const day = format(column.time, "yyyy-MM-dd");
    const base = isToday(column.time)
      ? todayLabel
      : format(column.time, "d MMM");
    column.label =
      (perDay.get(day) ?? 0) > 1
        ? `${base} ${format(column.time, "HH:mm")}`
        : base;
  }
}

/**
 * Turns a flat, recency-ordered list of readings into a grid: one column per
 * distinct `effective_datetime` (newest first), one row per requested code.
 *
 * Where a code and timestamp repeat, the first reading wins — the API returns
 * `-modified_date`, so that is the most recently amended one.
 */
export function pivotObservations(
  observations: ObservationListRead[],
  codes: Code[],
  todayLabel: string,
): { columns: PlotColumn[]; rows: PlotRow[] } {
  const requested = new Set(codes.map((code) => code.code));
  const columnsByKey = new Map<string, PlotColumn>();
  const unitByCode = new Map<string, string>();

  for (const observation of observations) {
    const codeKey = observation.main_code?.code;
    if (!codeKey || !requested.has(codeKey)) continue;

    const key = observation.effective_datetime;
    let column = columnsByKey.get(key);
    if (!column) {
      column = { key, time: new Date(key).getTime(), label: "", cells: {} };
      columnsByKey.set(key, column);
    }
    if (!column.cells[codeKey]) {
      column.cells[codeKey] = observation;
    }

    const unit = observation.value.unit?.display || observation.value.unit?.code;
    if (unit && !unitByCode.has(codeKey)) {
      unitByCode.set(codeKey, unit);
    }
  }

  const columns = Array.from(columnsByKey.values()).sort(
    (a, b) => b.time - a.time,
  );
  labelColumns(columns, todayLabel);

  const rows: PlotRow[] = codes.map((code) => ({
    code,
    key: code.code,
    label: code.display || code.code,
    unit: unitByCode.get(code.code),
  }));

  return { columns, rows };
}

/**
 * The chartable points for one code: numeric readings only, oldest first, one
 * per timestamp (matching the pivot's first-wins rule).
 */
export function seriesForCode(
  observations: ObservationListRead[],
  code: Code,
): PlotPoint[] {
  const seen = new Set<string>();
  const points: PlotPoint[] = [];

  for (const observation of observations) {
    if (observation.main_code?.code !== code.code) continue;
    if (seen.has(observation.effective_datetime)) continue;
    seen.add(observation.effective_datetime);

    const raw = observation.value.value;
    if (raw === null || raw === undefined || raw.trim() === "") continue;

    const value = Number(raw);
    if (!Number.isFinite(value)) continue;

    points.push({
      time: new Date(observation.effective_datetime).getTime(),
      value,
    });
  }

  return points.sort((a, b) => a.time - b.time);
}
```

