```ts
import { useInfiniteQuery } from "@tanstack/react-query";
import { useTranslation } from "react-i18next";

import query from "@/Utils/request/query";
import { PaginatedResponse } from "@/Utils/request/types";
import { Code } from "@/types/base/code/code";
import { ObservationListRead } from "@/types/emr/observation/observation";
import observationApi from "@/types/emr/observation/observationApi";

import {
  ObservationScope,
  PlotColumn,
  PlotPoint,
  PlotRow,
  buildObservationQueryParams,
  pivotObservations,
  seriesForCode,
} from "./observationPivot";

const LIMIT = 50;

interface UseObservationPlotDataArgs {
  patientId: string;
  encounterId: string;
  codes: Code[];
  scope: ObservationScope;
  /** The sheet is closed until first opened; skip fetching until then. */
  enabled: boolean;
}

interface ObservationPlotData {
  columns: PlotColumn[];
  rows: PlotRow[];
  seriesFor: (code: Code) => PlotPoint[];
  count: number;
  isLoading: boolean;
  hasNextPage: boolean;
  isFetchingNextPage: boolean;
  fetchNextPage: () => void;
}

export function useObservationPlotData({
  patientId,
  encounterId,
  codes,
  scope,
  enabled,
}: UseObservationPlotDataArgs): ObservationPlotData {
  const { t } = useTranslation();
  const codeKey = codes.map((code) => code.code).join(",");

  const { data, isLoading, hasNextPage, fetchNextPage, isFetchingNextPage } =
    useInfiniteQuery<PaginatedResponse<ObservationListRead>>({
      queryKey: ["observation-plot", patientId, encounterId, codeKey, scope],
      queryFn: async ({ pageParam, signal }) => {
        const response = await query(observationApi.list, {
          pathParams: { patientId },
          queryParams: buildObservationQueryParams({
            codes,
            encounterId,
            scope,
            offset: pageParam as number,
            limit: LIMIT,
          }),
        })({ signal });
        return response as PaginatedResponse<ObservationListRead>;
      },
      initialPageParam: 0,
      getNextPageParam: (lastPage, allPages) => {
        const nextOffset = allPages.length * LIMIT;
        return nextOffset < lastPage.count ? nextOffset : null;
      },
      enabled: enabled && codes.length > 0,
    });

  const observations = data?.pages.flatMap((page) => page.results) ?? [];
  const { columns, rows } = pivotObservations(observations, codes, t("today"));

  return {
    columns,
    rows,
    seriesFor: (code: Code) => seriesForCode(observations, code),
    count: data?.pages[0]?.count ?? 0,
    isLoading,
    hasNextPage: !!hasNextPage,
    isFetchingNextPage,
    fetchNextPage: () => {
      void fetchNextPage();
    },
  };
}
```

Note the pivot is called on every render rather than memoised. `codes` arrives as a prop and callers build it inline (`[item.main_code]`), so its identity changes each render and a `useMemo` keyed on it would recompute anyway — while a `useMemo` keyed on the joined string would go stale. The work is a single pass over at most a few hundred readings.

