import { ChevronLeft, ChevronRight } from "lucide-react";
import { useRef } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";

import { formatValue } from "@/components/Facility/ConsultationDetails/QuestionnaireResponsesList";

import { PlotColumn, PlotRow } from "./observationPivot";

interface ObservationFlowsheetTableProps {
  columns: PlotColumn[];
  rows: PlotRow[];
  hasNextPage: boolean;
  isFetchingNextPage: boolean;
  onLoadMore: () => void;
}

/** Treat "within 8px of the right edge" as having reached the oldest column. */
const EDGE_TOLERANCE = 8;

export function ObservationFlowsheetTable({
  columns,
  rows,
  hasNextPage,
  isFetchingNextPage,
  onLoadMore,
}: ObservationFlowsheetTableProps) {
  const { t } = useTranslation();
  const scrollRef = useRef<HTMLDivElement>(null);

  const scrollByPage = (direction: -1 | 1) => {
    const node = scrollRef.current;
    if (!node) return;
    node.scrollBy({ left: direction * node.clientWidth, behavior: "smooth" });
  };

  // Newest is leftmost, so scrolling right moves back in time. Reaching the
  // right edge is the request for another page.
  const handleScroll = () => {
    const node = scrollRef.current;
    if (!node || !hasNextPage || isFetchingNextPage) return;
    if (
      node.scrollLeft + node.clientWidth >=
      node.scrollWidth - EDGE_TOLERANCE
    ) {
      onLoadMore();
    }
  };

  if (columns.length === 0) {
    return (
      <div className="flex h-32 items-center justify-center text-sm text-gray-500">
        {t("no_readings_recorded")}
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-gray-200">
      <div className="flex items-center justify-between gap-2 px-4 py-3">
        <p className="text-sm text-gray-500">
          {t("showing_all_readings", { count: columns.length })}
        </p>
        <div className="flex gap-1">
          <Button
            variant="outline"
            size="icon"
            aria-label={t("newer")}
            onClick={() => scrollByPage(-1)}
          >
            <ChevronLeft className="size-4" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            aria-label={t("older")}
            onClick={() => scrollByPage(1)}
          >
            <ChevronRight className="size-4" />
          </Button>
        </div>
      </div>

      <div
        ref={scrollRef}
        onScroll={handleScroll}
        className="overflow-x-auto"
        data-cy="observation-flowsheet-scroll"
      >
        <table className="w-full border-collapse text-sm">
          <thead>
            <tr className="bg-gray-50">
              <th className="sticky left-0 z-10 min-w-56 bg-gray-50 px-4 py-2 text-left font-medium text-gray-600">
                {t("component")}
              </th>
              {columns.map((column) => (
                <th
                  key={column.key}
                  className="min-w-24 whitespace-nowrap px-4 py-2 text-left font-medium text-gray-600"
                >
                  {column.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.key} className="border-t border-gray-100">
                <th
                  scope="row"
                  className="sticky left-0 z-10 bg-white px-4 py-2 text-left font-medium text-gray-900"
                >
                  <span className="block truncate" title={row.label}>
                    {row.label}
                  </span>
                  {row.unit && (
                    <span className="text-xs font-normal text-gray-500">
                      {row.unit}
                    </span>
                  )}
                </th>
                {columns.map((column) => {
                  const cell = column.cells[row.key];
                  return (
                    <td
                      key={column.key}
                      className={cn(
                        "whitespace-nowrap px-4 py-2",
                        cell ? "text-gray-900" : "text-gray-400",
                      )}
                    >
                      {cell
                        ? formatValue(cell.value.value, cell.value_type) || "-"
                        : "-"}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isFetchingNextPage && (
        <p className="px-4 py-2 text-xs text-gray-500">{t("loading")}</p>
      )}
    </div>
  );
}
```

