import { format } from "date-fns";
import { useTranslation } from "react-i18next";
import {
  CartesianGrid,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import { PlotPoint } from "./observationPivot";

interface ObservationTrendChartProps {
  points: PlotPoint[];
  label: string;
  unit?: string;
  height?: number;
}

export function ObservationTrendChart({
  points,
  label,
  unit,
  height = 280,
}: ObservationTrendChartProps) {
  const { t } = useTranslation();

  // Nothing numeric to plot — a blood group, a free-text note. The table still
  // shows the readings; a chart would only be an empty box.
  if (points.length === 0) return null;

  const latest = points[points.length - 1];

  return (
    <section>
      <div className="mb-2 flex items-baseline justify-between gap-4">
        <h3 className="text-base font-semibold text-gray-900">
          {t("observation_trend", { name: label })}
        </h3>
        <p className="text-sm text-gray-500">
          {t("latest")}{" "}
