### Task 5: Sheet shell

Composes the chart and the table, and owns the only two pieces of UI state: which code is active and which scope is showing. Follows the trigger-wrapper idiom already used by `ObservationHistorySheet`, so call sites read like the ones already in the codebase.

**Files:**
- Create: `src/components/Common/Charts/observation-plot-sheet/ObservationPlotSheet.tsx`

**Interfaces:**
- Consumes: `useObservationPlotData` (Task 2), `ObservationFlowsheetTable` (Task 3), `ObservationTrendChart` (Task 4), `ObservationScope` (Task 1).
- Produces: `ObservationPlotSheet` with props `{ children, patientId, encounterId, codes, title?, initialCode? }`. Tasks 6 and 7 render it.

- [ ] **Step 1: Write the sheet**

Create `src/components/Common/Charts/observation-plot-sheet/ObservationPlotSheet.tsx`:

```tsx
import { format } from "date-fns";
import { ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";

import { Code } from "@/types/base/code/code";

import { ObservationFlowsheetTable } from "./ObservationFlowsheetTable";
import { ObservationTrendChart } from "./ObservationTrendChart";
import { ObservationScope } from "./observationPivot";
import { useObservationPlotData } from "./useObservationPlotData";

interface ObservationPlotSheetProps {
  children: ReactNode;
  patientId: string;
  encounterId: string;
  /** One code for a single observation, several for a panel. */
  codes: Code[];
  title?: string;
  initialCode?: Code;
}

export function ObservationPlotSheet({
  children,
  patientId,
  encounterId,
  codes,
  title,
  initialCode,
}: ObservationPlotSheetProps) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const [scope, setScope] = useState<ObservationScope>("encounter");
  const [activeCodeKey, setActiveCodeKey] = useState(
    initialCode?.code ?? codes[0]?.code,
  );

  const activeCode = codes.find((c) => c.code === activeCodeKey) ?? codes[0];

  const {
    columns,
    rows,
    seriesFor,
    count,
    isLoading,
    hasNextPage,
    isFetchingNextPage,
    fetchNextPage,
  } = useObservationPlotData({
    patientId,
    encounterId,
    codes,
    scope,
    enabled: open,
  });

  const heading = title || activeCode?.display || t("observations");
  const activeRow = rows.find((row) => row.key === activeCode?.code);

  // The range describes what is loaded, and grows as more pages arrive.
  const oldest = columns[columns.length - 1];
  const newest = columns[0];
  const range =
    oldest && newest
      ? `${format(oldest.time, "d MMM")} → ${format(newest.time, "d MMM")}`
      : null;

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger asChild>{children}</SheetTrigger>
      <SheetContent
        side="right"
        className="flex w-full flex-col gap-6 overflow-y-auto sm:max-w-4xl"
      >
        <SheetHeader className="space-y-1">
          <SheetTitle>{heading}</SheetTitle>
          <SheetDescription>
            {[
              scope === "encounter"
                ? t("this_encounter")
                : t("include_previous"),
              t("n_recordings", { count }),
              range,
            ]
              .filter(Boolean)
              .join(" • ")}
          </SheetDescription>
        </SheetHeader>

        <div className="flex flex-wrap items-center justify-between gap-2">
          {codes.length > 1 ? (
            <div className="flex flex-wrap gap-1 rounded-lg bg-gray-100 p-1">
              {codes.map((code) => (
                <button
                  key={code.code}
                  type="button"
                  onClick={() => setActiveCodeKey(code.code)}
                  className={cn(
                    "rounded-md px-3 py-1.5 text-sm font-medium transition",
                    code.code === activeCode?.code
                      ? "bg-white text-gray-900 shadow-sm"
                      : "text-gray-600 hover:text-gray-900",
                  )}
                >
                  {code.display || code.code}
                </button>
              ))}
            </div>
          ) : (
            <span />
          )}

          <div className="flex gap-1 rounded-lg bg-gray-100 p-1">
            <Button
              variant={scope === "encounter" ? "white" : "ghost"}
              size="sm"
              onClick={() => setScope("encounter")}
            >
              {t("this_encounter")}
            </Button>
            <Button
              variant={scope === "patient" ? "white" : "ghost"}
              size="sm"
              onClick={() => setScope("patient")}
            >
              {t("include_previous")}
            </Button>
          </div>
        </div>

        {isLoading ? (
          <div className="space-y-3">
            <Skeleton className="h-64 w-full" />
            <Skeleton className="h-32 w-full" />
          </div>
        ) : (
          <>
            {activeCode && (
              <ObservationTrendChart
                points={seriesFor(activeCode)}
                label={activeCode.display || activeCode.code}
                unit={activeRow?.unit}
              />
            )}
            <ObservationFlowsheetTable
              columns={columns}
              rows={rows}
              hasNextPage={hasNextPage}
              isFetchingNextPage={isFetchingNextPage}
              onLoadMore={fetchNextPage}
            />
          </>
        )}
      </SheetContent>
    </Sheet>
  );
}
```

